'use strict';
/* public/js/30-npcs.js -- Mr. Sir, the Warden, the D Tent crew (including tent breaks). Generated by scripts/split-client.mjs; see ARCHITECTURE.md. */
/* ---------- NPCs ---------- */
const sir=makePerson({suit:0xb9a47a,shirt:0xb9a47a,skin:0xe0b08a,hat:'cowboy',shades:true,shovel:false,body:'stocky',band:0x3a2a1e});
sir.g.position.set(1.2,baseH(1.2,34),34);sir.g.rotation.y=Math.PI;scene.add(sir.g);
const sirL=makeLabel(sir.g,'Mr. Sir','npc');
const warden=makePerson({suit:0x2c2c2c,shirt:0xd9d9d9,skin:0xe8c29c,hat:'cowboy',shovel:false,body:'tall',band:0x8a3a1c});
warden.g.position.set(-34,baseH(-34,41)+0.2,41.2);warden.g.rotation.y=Math.PI;scene.add(warden.g);
const wardenL=makeLabel(warden.g,'The Warden','npc');
const SPOTS=[
  {id:'sir',x:1.4,z:32.6,r:3.6},
  {id:'store',x:16,z:41.2,r:3.4},
  {id:'warden',x:-34,z:40,r:2.0},
  {id:'cards',x:D_TENT.table.x,z:D_TENT.table.z,r:1.6},   // moved inside D Tent (see "tent interiors" above)
];
/* tent doors (outside: press E or F to go in), and, once inside, the way back out and every bunk.
   These reuse the tent's real x/z, but the outdoor solid() footprint keeps anyone outside from ever standing
   close enough to trigger them by accident - they're only reachable via enterTent()/the teleport it does. */
TENTS.forEach((t,ti)=>{
  SPOTS.push({id:'tentdoor',ti,x:t.x,z:t.z-t.hd-1.3,r:1.4});   // outside, at the flap on the camp-facing side
  SPOTS.push({id:'exit',ti,x:t.x,z:t.z-t.roomD+0.85,r:1.4});
  if(t.house)SPOTS.push({id:'office',ti,x:t.desk.x,z:t.desk.z,r:1.8});
});
BUNKS.forEach((b,bi)=>SPOTS.push({id:'bunk',bi,x:b.x,z:b.z,r:1.2}));

/* the D Tent crew (they're here even when your friends aren't) */
const BOTDEF=[
  {n:'X-Ray',skin:0x6b4a35,band:0x3a3a3a,hat:'desert',body:'slim',x:-14,z:20,rate:0.07,lines:['Anything shiny, you bring it to me first.','You dig like a lawn chair.','I can\'t see a thing without my glasses.']},
  {n:'Armpit',skin:0x5a3b28,band:0x8a2020,hat:'bucket',body:'stocky',x:-8,z:22,rate:0.06,lines:['My back is killing me.','Is it lunch yet?','Don\'t call me Armpit. Fine, call me Armpit.']},
  {n:'Squid',skin:0xe0b48f,band:0x2f5f8a,hat:'desert',body:'average',x:-2.5,z:19.5,rate:0.065,lines:['This lake has been dry for a hundred years.','Keep your eyes on the ground, new kid.','I\'m not crying. It\'s the sun.']},
  {n:'Zigzag',skin:0xf0c9a2,band:0x6b2f8a,hat:'none',hair:0xb88a4a,body:'tall',x:4,z:21.5,rate:0.07,lines:['I can hear the dirt talking.','What if the whole lake is one big hole?','The Warden has cameras in the tents.']},
  {n:'Magnet',skin:0xb07a52,band:0xc78a1a,hat:'bucket',body:'short',x:10,z:19,rate:0.06,lines:['Who took my sunflower seeds?','Things just stick to my hands.','Mr. Sir is coming. Look busy.']},
  {n:'Zero',skin:0x4a3021,band:0xd9d2c0,hat:'none',hair:0x1f1511,body:'slim',x:16,z:22,rate:0.15,lines:['I like digging holes.','I\'m already done with mine.','Want me to dig part of yours?']},
];
const botRng=mulberry32((Date.now()/1000)|0);
const bots=BOTDEF.map(d=>{
  const p=makePerson({skin:d.skin,band:d.band,hat:d.hat,body:d.body,hair:d.hair});scene.add(p.g);
  const hole=addHole({x:r1(d.x),z:r1(d.z),d:0.2+botRng()*1.0,bot:true});touchHole(hole);
  p.g.position.set(hole.x,groundAt(hole.x,hole.z),hole.z);p.g.rotation.y=Math.PI+(botRng()-0.5);
  const L=makeLabel(p.g,d.n,'bot');
  return{d,p,hole,L,state:'dig',t:0,dph:botRng(),talkT:4+botRng()*20,tx:0,tz:0};
});
/* the D Tent door, from outside: where the crew walks to before ducking in for a break or the night */
const D_TENT_DOOR={x:D_TENT.x,z:D_TENT.z-D_TENT.hd-1.3};
/* X-Ray always deals; everyone else gets one of D Tent's bunks (there are 6, one more than the 5 who need one) */
const D_TENT_BUNKS=BUNKS.map((b,i)=>({b,i})).filter(o=>o.b.tent===TENTS.indexOf(D_TENT)).map(o=>o.i);
const BOT_BUNK={};BOTDEF.filter(d=>d.n!=='X-Ray').forEach((d,i)=>{BOT_BUNK[d.n]=D_TENT_BUNKS[i]});
function botIndoorSpot(b){return b.d.n==='X-Ray'?D_TENT.dealerSeat:BUNKS[BOT_BUNK[b.d.n]]}
function updateBots(dt,now){
  if(PARTY.on)return;
  const isNight=clockT()>=DAYMS;
  for(const b of bots){
    if(b.sinkOverride)continue;   // off pulling someone out of a sinkhole right now (87-sinkhole.js drives him instead)
    const g=b.p.g;
    g.visible=b.state!=='inside'||S.tent===TENTS.indexOf(D_TENT);
    if(DLG.open&&DLG.bot===b){ /* mid-conversation: stop and face the player */
      let dr=Math.atan2(P.x-g.position.x,P.z-g.position.z)-g.rotation.y;dr=Math.atan2(Math.sin(dr),Math.cos(dr));g.rotation.y+=dr*Math.min(1,dt*8);
      animPerson(b.p,0,dt);continue;
    }
    b.talkT-=dt;if(b.talkT<=0){b.talkT=18+botRng()*28;say(b.L,b.d.lines[Math.floor(botRng()*b.d.lines.length)])}
    if(b.state==='inside'){
      /* hanging out in D Tent: sitting at the table (X-Ray) or lying on a bunk (everyone else) */
      if(b.d.n==='X-Ray'){g.position.y=TENT_FLOOR_Y;animPerson(b.p,0,dt)}          // dealing at the card table
      else{animPerson(b.p,0,dt);sleepPose(b.p,botIndoorSpot(b))}                      // everyone else lies on their own bunk
      b.t-=dt;
      if(!isNight&&b.t<=0){b.state='leaving';b.tx=D_TENT_DOOR.x;b.tz=D_TENT_DOOR.z}
      continue;
    }
    if(b.state==='dig'){
      const iv=b.d.rate>0.1?0.7:0.95,prev=b.dph;b.dph+=dt/iv;
      /* dirt leaves the shovel at the top of the toss and lands on this hole's pile */
      if(prev<0.72&&b.dph>=0.72&&nearCam(b.hole.x,b.hole.z,35)){const ux=b.hole.mx-g.position.x,uz=b.hole.mz-g.position.z,ul=Math.hypot(ux,uz)||1;puff(g.position.x+ux/ul*0.5,g.position.y+1.3,g.position.z+uz/ul*0.5,b.hole.mx,b.hole.mz,5)}
      if(b.dph>=1){b.dph-=1;b.hole.d=Math.min(FIVE_FT,b.hole.d+b.d.rate*1.25);touchHole(b.hole)}
      /* stand in the hole with the dirt pile on the throwing side, and sink as it gets deeper */
      const ux=b.hole.mx-b.hole.x,uz=b.hole.mz-b.hole.z,ty=Math.atan2(-uz,ux);
      let dr=ty-g.rotation.y;dr=Math.atan2(Math.sin(dr),Math.cos(dr));g.rotation.y+=dr*Math.min(1,dt*5);
      g.position.x+=(b.hole.x-g.position.x)*Math.min(1,dt*4);g.position.z+=(b.hole.z-g.position.z)*Math.min(1,dt*4);
      g.position.y=groundAt(g.position.x,g.position.z);
      animPerson(b.p,2,dt,b.dph%1);
      if(b.hole.d>=FIVE_FT){
        b.state='rest';b.t=6+botRng()*6;b.restT=0;
        if(botRng()<0.3){const ty2=['cap','can','spoon'][Math.floor(botRng()*3)];popItem({type:ty2},b.hole.x,b.hole.z);say(b.L,{cap:'Just a bottle cap. Figures.',can:'A rusty can. Great.',spoon:'Somebody lost a spoon out here.'}[ty2])}
      }
    }else if(b.state==='rest'){
      b.restT+=dt;b.t-=dt;
      g.position.y=groundAt(g.position.x,g.position.z);
      animPerson(b.p,b.restT<2.2?5:b.restT<3.8?6:0,dt);
      if(b.t<=0){
        /* at night the crew heads back to D Tent to sleep; by day they'll wander over for a break sometimes */
        if(isNight||botRng()<0.22){b.state='gateout';b.tx=0;b.tz=25}
        else{
          for(let k=0;k<20;k++){const a=botRng()*Math.PI*2;const x=r1(b.hole.x+Math.cos(a)*3.3),z=r1(clamp(b.hole.z+Math.sin(a)*3.3,14,26));if(!holeNear(x,z,2.9)){b.tx=x;b.tz=z;break}}
          if(b.tx||b.tz)b.state='walk';else b.t=4;
        }
      }
    }else{
      const dx=b.tx-g.position.x,dz=b.tz-g.position.z,d=Math.hypot(dx,dz);
      if(d<0.1&&b.state==='return'){b.tx=b.tz=0;b.state=b.hole.d>=FIVE_FT?'rest':'dig';b.t=2;b.restT=0;b.dph=0}
      else if(d<0.1&&b.state==='gateout'){b.state='gatein';b.tx=0;b.tz=30}
      else if(d<0.1&&b.state==='gatein'){b.state='gotent';b.tx=D_TENT_DOOR.x;b.tz=D_TENT_DOOR.z}
      else if(d<0.1&&b.state==='gotent'){
        const spot=botIndoorSpot(b);g.position.set(spot.x,TENT_FLOOR_Y,spot.z);b.state='inside';b.t=20+botRng()*40;
      }
      else if(d<0.1&&b.state==='leaving'){g.position.set(D_TENT_DOOR.x,groundAt(D_TENT_DOOR.x,D_TENT_DOOR.z),D_TENT_DOOR.z);b.state='gatebackin';b.tx=0;b.tz=30}
      else if(d<0.1&&b.state==='gatebackin'){b.state='gatebackout';b.tx=0;b.tz=25}
      else if(d<0.1&&b.state==='gatebackout'){b.state='return';b.tx=b.hole.x;b.tz=b.hole.z}
      else if(d<0.1){b.hole=addHole({x:b.tx,z:b.tz,d:0.05,bot:true});b.tx=b.tz=0;b.state='dig';b.dph=0;touchHole(b.hole)}
      else{const s=Math.min(d,dt*(b.state==='return'?3.5:2.2));g.position.x+=dx/d*s;g.position.z+=dz/d*s;g.rotation.y=Math.atan2(dx,dz);g.position.y=groundAt(g.position.x,g.position.z);animPerson(b.p,1,dt)}
    }
  }
}
